// WP-3.1 virtual shadow maps: see include/fuse/renderer/shadow/vsm/virtual_shadow_map.hpp.
#include <fuse/renderer/shadow/vsm/virtual_shadow_map.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp31.cmake from src/shadow/vsm/shaders/*: kVsm<Kernel><Slang|Glsl>Spv and
// FUSE_VSM_{SLANG,GLSL} when every kernel of a language exists.
#include "vsm_spv.h"
#endif

namespace fuse::renderer::vsm {

namespace {
constexpr u32 kFrameStride = 1280u; ///< ring slot (>= sizeof(VsmFrameConstants), 256-aligned)
static_assert(sizeof(VsmFrameConstants) <= kFrameStride, "frame ring slot");
constexpr u32 kPoolFormat = 98u;    ///< VK_FORMAT_R32_UINT
constexpr u32 kCounterInit[kCounterCount] = {0u, 1u, 1u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u};

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }
u32 groups(u32 items, u32 size) { return items == 0u ? 1u : (items + size - 1u) / size; }

#if defined(FUSE_VULKAN_BACKEND)
struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
#endif
} // namespace

VsmWorkLayout VsmWorkLayout::compute(u32 levels, u32 physPages) {
    VsmWorkLayout l{};
    const u64 words = (static_cast<u64>(levels) * kPagesPerLevel + 31u) / 32u;
    u64 cursor = 0;
    auto take = [&](u64 bytes) {
        const u64 at = cursor;
        cursor = align256(cursor + (bytes > 4u ? bytes : 4u));
        return at;
    };
    l.counters = take(kCounterCount * 4u);
    l.request = take(words * 4u);
    l.need = take(words * 4u);
    l.resetBytes = cursor - l.request;
    l.renderList = take(static_cast<u64>(physPages) * 8u);
    l.candidates = take(static_cast<u64>(physPages) * 4u);
    l.bytes = cursor;
    return l;
}

VsmCapabilities queryVsmCapabilities(const VulkanDevice* device) {
    VsmCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const RendererCaps& caps = device->info().caps;
    if (!caps.bufferDeviceAddress || !caps.shaderInt64) {
        c.reason = "bufferDeviceAddress / shaderInt64 missing";
        return c;
    }
    VkFormatProperties props{};
    vkGetPhysicalDeviceFormatProperties(static_cast<VkPhysicalDevice>(device->nativePhysicalDevice()),
                                        static_cast<VkFormat>(kPoolFormat), &props);
    if ((props.optimalTilingFeatures & VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT) == 0u) {
        c.reason = "R32_UINT storage images unsupported";
        return c;
    }
    c.vsm = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

VirtualShadowMap::~VirtualShadowMap() { destroy(); }

bool VirtualShadowMap::init(const VirtualShadowMapDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u || desc.poolPagesX == 0u ||
        desc.poolPagesY == 0u || desc.poolPagesX > kMaxPoolPagesPerAxis || desc.poolPagesY > kMaxPoolPagesPerAxis) {
        return false;
    }
    if (!queryVsmCapabilities(desc.device).vsm || !m_clipmap.init(desc.clipmap)) {
        return false;
    }
    const u32 levels = desc.clipmap.levels;
    const u32 phys = desc.poolPagesX * desc.poolPagesY;
    m_layout = VsmWorkLayout::compute(levels, phys);
    m_retired.reserve(8);
    m_initialized = true; // destroy() releases partial state from here on
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFrameStride;
    ring.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress));
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "vsm.frame";
    m_boundsCapacity = desc.instanceCapacity > 0u ? desc.instanceCapacity : 1u;
    SamplerDesc point{};
    point.addressMode = 2u; // CLAMP_TO_EDGE
    point.maxLod = 0.f;
    point.name = "vsm.point";
    m_sampler = m_desc.bindless->acquireSampler(point);
    if (!m_sampler.isValid() || !m_desc.allocator->createBuffer(ring, m_frameRing) || m_frameRing.mapped == nullptr ||
        m_frameRing.deviceAddress == 0u || !createPipelines() ||
        !createBuffer(m_pageTable, static_cast<u64>(levels) * kPagesPerLevel * 4u, false, "vsm.page_table") ||
        !createBuffer(m_physMeta, static_cast<u64>(phys) * 8u, false, "vsm.phys_meta") ||
        !createBuffer(m_work, m_layout.bytes, true, "vsm.work") ||
        !createBuffer(m_bounds, static_cast<u64>(m_boundsCapacity) * 2u * sizeof(VsmBoundsRecord), false, "vsm.bounds")) {
        destroy();
        return false;
    }
    m_samplerHandle = m_desc.bindless->shaderHandle(m_sampler);
    TextureDesc td{};
    td.width = desc.poolPagesX * kPageTexels;
    td.height = desc.poolPagesY * kPageTexels;
    td.format = static_cast<GpuFormat>(kPoolFormat);
    td.usage = static_cast<ImageUsage>(static_cast<u32>(ImageUsage::Storage) | static_cast<u32>(ImageUsage::Sampled) |
                                       static_cast<u32>(ImageUsage::TransferSrc));
    td.name = "vsm.pool";
    if (!m_desc.allocator->createImage(td, m_pool.image)) {
        m_pool = Pool{};
        destroy();
        return false;
    }
    m_poolSlot = m_desc.bindless->registerTextureSlot(m_pool.image, true);
    if (!m_poolSlot.isValid()) {
        destroy();
        return false;
    }
    m_poolHandle = m_desc.bindless->shaderHandle(m_poolSlot);
    m_needInit = true;
    m_boundsDirty = true;
    m_stats.boundsRebuilds = 1u;
    return true;
#else
    return false;
#endif
}

void VirtualShadowMap::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    destroyBuffer(m_pageTable);
    destroyBuffer(m_physMeta);
    destroyBuffer(m_work);
    destroyBuffer(m_bounds);
    if (m_poolSlot.isValid()) {
        m_desc.bindless->unregisterSlot(m_poolSlot);
    }
    if (m_pool.image.image != nullptr) {
        m_desc.allocator->destroyImage(m_pool.image);
    }
    if (m_frameRing.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_frameRing);
    }
    if (m_sampler.isValid()) {
        m_desc.bindless->releaseSampler(m_sampler);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void*& pipeline : m_pipelines) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
            pipeline = nullptr;
        }
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_layoutHandle = nullptr;
    m_pool = Pool{};
    m_poolSlot = BindlessSlotHandle{};
    m_poolHandle = 0;
    m_sampler = BindlessSlotHandle{};
    m_samplerHandle = 0;
    m_frameRing = Buffer{};
    m_frameAddress = 0;
    m_retired.clear();
    m_recordCount = 0;
    m_boundsCapacity = 0;
    m_boundsParity = 0;
    m_lastInstanceCount = 0;
    m_constants = VsmFrameConstants{};
    m_clipmap.reset();
    m_language = "none";
    m_stats = VsmStats{};
    m_initialized = false;
}

bool VirtualShadowMap::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    Code k[kKernelCount]{};
    bool found = false;
#if defined(FUSE_VSM_SLANG)
    if (m_desc.language == VsmKernelLanguage::Auto || m_desc.language == VsmKernelLanguage::Slang) {
        k[kMark] = code(kVsmMarkSlangSpv);
        k[kInvalidate] = code(kVsmInvalidateSlangSpv);
        k[kUpdate] = code(kVsmUpdateSlangSpv);
        k[kAlloc] = code(kVsmAllocSlangSpv);
        k[kRender] = code(kVsmRenderSlangSpv);
        k[kClear] = code(kVsmClearSlangSpv);
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_VSM_GLSL)
    if (!found && (m_desc.language == VsmKernelLanguage::Auto || m_desc.language == VsmKernelLanguage::Glsl)) {
        k[kMark] = code(kVsmMarkGlslSpv);
        k[kInvalidate] = code(kVsmInvalidateGlslSpv);
        k[kUpdate] = code(kVsmUpdateGlslSpv);
        k[kAlloc] = code(kVsmAllocGlslSpv);
        k[kRender] = code(kVsmRenderGlslSpv);
        k[kClear] = code(kVsmClearGlslSpv);
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(VsmPush)};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    for (u32 i = 0; i < kKernelCount; ++i) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = k[i].bytes;
        moduleInfo.pCode = k[i].words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = module;
        info.stage.pName = "main";
        info.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, module, nullptr);
        m_pipelines[i] = pipeline;
        if (result != VK_SUCCESS) {
            return false;
        }
    }
    return true;
#else
    return false;
#endif
}

bool VirtualShadowMap::createBuffer(OwnedBuffer& out, u64 bytes, bool indirect, const char* name) {
    out = OwnedBuffer{};
    BufferDesc desc{};
    desc.size = static_cast<usize>(bytes);
    desc.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::TransferDst) |
                                          static_cast<u32>(BufferUsage::TransferSrc) |
                                          static_cast<u32>(BufferUsage::ShaderDeviceAddress) |
                                          (indirect ? static_cast<u32>(BufferUsage::Indirect) : 0u));
    desc.memoryUsage = MemoryUsage::GpuOnly;
    desc.name = name;
    if (!m_desc.allocator->createBuffer(desc, out.buffer) || out.buffer.deviceAddress == 0u) {
        if (out.buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(out.buffer);
        }
        out = OwnedBuffer{};
        return false;
    }
    out.slot = m_desc.bindless->registerBufferSlot(out.buffer, false);
    out.handle = m_desc.bindless->shaderHandle(out.slot);
    if (!out.slot.isValid()) {
        destroyBuffer(out);
        return false;
    }
    return true;
}

void VirtualShadowMap::destroyBuffer(OwnedBuffer& b) {
    if (b.slot.isValid()) {
        m_desc.bindless->unregisterSlot(b.slot);
    }
    if (b.buffer.handle != nullptr) {
        m_desc.allocator->destroyBuffer(b.buffer);
    }
    b = OwnedBuffer{};
}

u32 VirtualShadowMap::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        destroyBuffer(m_retired[i].buffer);
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = static_cast<u32>(m_retired.size());
    return collected;
}

bool VirtualShadowMap::beginFrame(u64 frameSerial, const VsmFrameDesc& frame) {
    if (!m_initialized) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.passes = 0;
    if (frame.instanceCount > m_boundsCapacity) {
        u32 grown = m_boundsCapacity;
        while (grown < frame.instanceCount) {
            grown = grown > 0x40000000u ? frame.instanceCount : grown * 2u;
        }
        OwnedBuffer fresh{};
        if (!createBuffer(fresh, static_cast<u64>(grown) * 2u * sizeof(VsmBoundsRecord), false, "vsm.bounds")) {
            return false;
        }
        m_retired.push_back(Retired{m_bounds, frameSerial});
        m_stats.retired = static_cast<u32>(m_retired.size());
        m_bounds = fresh;
        m_boundsCapacity = grown;
        m_boundsDirty = true;
        ++m_stats.boundsRebuilds;
    } else if (frame.instanceCount < m_lastInstanceCount && !m_boundsDirty) {
        // Slots past the new count stop being tracked in one half only: restart the history.
        m_boundsDirty = true;
        ++m_stats.boundsRebuilds;
    }
    VsmFrameConstants c = m_constants;
    if (!m_clipmap.build(frame.view, c)) {
        return false;
    }
    m_lastInstanceCount = frame.instanceCount;
    c.pageTable = m_pageTable.buffer.deviceAddress;
    c.physMeta = m_physMeta.buffer.deviceAddress;
    c.work = m_work.buffer.deviceAddress;
    c.bounds = m_bounds.buffer.deviceAddress;
    c.physPages = physPages();
    c.poolPagesX = m_desc.poolPagesX;
    c.depthTexture = frame.depthHandle;
    c.depthSampler = m_samplerHandle;
    c.instanceCount = frame.instanceCount;
    c.scene = frame.scene;
    c.pageTableHandle = m_pageTable.handle;
    c.physMetaHandle = m_physMeta.handle;
    c.workHandle = m_work.handle;
    c.boundsHandle = m_bounds.handle;
    c.poolHandle = m_poolHandle;
    c.clearValue = m_desc.clearValue;
    c.offRequest = static_cast<u32>(m_layout.request / 4u);
    c.offNeed = static_cast<u32>(m_layout.need / 4u);
    c.offRenderList = static_cast<u32>(m_layout.renderList / 4u);
    c.offCandidates = static_cast<u32>(m_layout.candidates / 4u);
    c.boundsCapacity = m_boundsCapacity;
    // Ping-pong halves: vsm.invalidate reads last frame's half and writes the other one.
    c.boundsRead = m_boundsParity == 0u ? 0u : m_boundsCapacity;
    c.boundsWrite = m_boundsParity == 0u ? m_boundsCapacity : 0u;
    m_constants = c;
    const u64 offset = (frameSerial % m_desc.framesInFlight) * kFrameStride;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + offset, &m_constants, sizeof(m_constants));
    m_frameAddress = m_frameRing.deviceAddress + offset;
    return true;
}

VsmGraphRefs VirtualShadowMap::importInto(rg::Graph& graph) {
    VsmGraphRefs refs{};
    if (!m_initialized) {
        return refs;
    }
    auto import = [&](OwnedBuffer& b, const char* name) {
        return graph.importBuffer(rg::ImportedBuffer{b.buffer.handle, b.buffer.desc.size, b.queue, &b.queue, name});
    };
    refs.pageTable = import(m_pageTable, "vsm.page_table");
    refs.physMeta = import(m_physMeta, "vsm.phys_meta");
    refs.work = import(m_work, "vsm.work");
    refs.bounds = import(m_bounds, "vsm.bounds");
    rg::ImportedImage i{};
    i.image = m_pool.image.image;
    i.view = m_pool.image.view;
    i.format = kPoolFormat;
    i.width = m_desc.poolPagesX * kPageTexels;
    i.height = m_desc.poolPagesY * kPageTexels;
    i.initialLayout = m_pool.layout;
    i.initialQueue = m_pool.queue;
    i.layoutTracker = &m_pool.layout;
    i.queueTracker = &m_pool.queue;
    i.name = "vsm.pool";
    refs.pool = graph.importImage(i);
    return refs;
}

VirtualShadowMap::PassRecord* VirtualShadowMap::nextRecord(RecordKind kind, u32 kernel) {
    if (m_recordCount >= kMaxPasses) {
        return nullptr;
    }
    PassRecord* r = &m_records[m_recordCount++];
    *r = PassRecord{};
    r->self = this;
    r->kind = kind;
    r->kernel = kernel;
    r->push.constants = m_frameAddress;
    ++m_stats.passes;
    return r;
}

void VirtualShadowMap::addMarking(rg::Graph& graph, const VsmGraphRefs& refs, rg::TextureRef depth) {
    if (!m_initialized || !refs.work.valid() || !depth.valid() || m_recordCount + 3u > kMaxPasses) {
        return;
    }
    if (m_needInit) {
        PassRecord* r = nextRecord(kInit, 0u);
        graph.addPass("vsm.init", &VirtualShadowMap::recordPass, r)
            .use(refs.pageTable, rg::Access::TransferDst)
            .use(refs.physMeta, rg::Access::TransferDst);
        m_needInit = false;
    }
    {
        PassRecord* r = nextRecord(kReset, 0u);
        graph.addPass("vsm.reset", &VirtualShadowMap::recordPass, r)
            .use(refs.work, rg::Access::TransferDst, rg::BufferRange{0, m_layout.request + m_layout.resetBytes});
    }
    {
        PassRecord* r = nextRecord(kDispatch, kMark);
        r->groups[0] = groups(m_constants.depthWidth, kMarkTile);
        r->groups[1] = groups(m_constants.depthHeight, kMarkTile);
        graph.addPass("vsm.mark", &VirtualShadowMap::recordPass, r)
            .use(depth, rg::Access::SampledRead, {}, rg::kStageCompute)
            .use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
}

void VirtualShadowMap::addInvalidation(rg::Graph& graph, const VsmGraphRefs& refs, const gpu_scene::GpuSceneGraphRefs& scene) {
    if (!m_initialized || !refs.bounds.valid() || m_recordCount + 2u > kMaxPasses) {
        return;
    }
    if (m_boundsDirty) {
        PassRecord* r = nextRecord(kBoundsClear, 0u);
        graph.addPass("vsm.bounds_clear", &VirtualShadowMap::recordPass, r).use(refs.bounds, rg::Access::TransferDst);
        m_boundsDirty = false;
    }
    PassRecord* r = nextRecord(kDispatch, kInvalidate);
    r->groups[0] = groups(m_constants.instanceCount, kLinearGroup);
    r->groups[1] = m_constants.levels;
    rg::PassBuilder pass = graph.addPass("vsm.invalidate", &VirtualShadowMap::recordPass, r);
    gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageCompute);
    pass.use(refs.bounds, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
        .use(refs.pageTable, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
        .use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    m_boundsParity ^= 1u;
}

void VirtualShadowMap::addAllocation(rg::Graph& graph, const VsmGraphRefs& refs) {
    if (!m_initialized || !refs.pageTable.valid() || m_recordCount + 3u > kMaxPasses) {
        return;
    }
    const u32 pages = m_constants.virtualPages;
    {
        PassRecord* r = nextRecord(kDispatch, kUpdate);
        r->groups[0] = groups(pages, kLinearGroup);
        graph.addPass("vsm.update", &VirtualShadowMap::recordPass, r)
            .use(refs.pageTable, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
            .use(refs.physMeta, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
            .use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
    {
        PassRecord* r = nextRecord(kDispatch, kAlloc);
        r->groups[0] = 1u;
        graph.addPass("vsm.alloc", &VirtualShadowMap::recordPass, r)
            .use(refs.pageTable, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
            .use(refs.physMeta, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
            .use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
    {
        PassRecord* r = nextRecord(kDispatch, kRender);
        r->groups[0] = groups(pages, kLinearGroup);
        graph.addPass("vsm.render", &VirtualShadowMap::recordPass, r)
            .use(refs.pageTable, rg::Access::StorageReadWrite, {}, rg::kStageCompute)
            .use(refs.work, rg::Access::StorageReadWrite, {}, rg::kStageCompute);
    }
}

void VirtualShadowMap::addClearPages(rg::Graph& graph, const VsmGraphRefs& refs) {
    if (!m_initialized || !refs.pool.valid() || m_recordCount + 1u > kMaxPasses) {
        return;
    }
    PassRecord* r = nextRecord(kDispatchIndirect, kClear);
    graph.addPass("vsm.clear", &VirtualShadowMap::recordPass, r)
        .use(refs.work, rg::Access::IndirectRead)
        .use(refs.work, rg::Access::StorageRead, {}, rg::kStageCompute)
        .use(refs.pool, rg::Access::StorageWrite, {}, rg::kStageCompute);
}

void VirtualShadowMap::addFrame(rg::Graph& graph, const VsmGraphRefs& refs, rg::TextureRef depth,
                                const gpu_scene::GpuSceneGraphRefs& scene, bool clearPages) {
    addMarking(graph, refs, depth);
    addInvalidation(graph, refs, scene);
    addAllocation(graph, refs);
    if (clearPages) {
        addClearPages(graph, refs);
    }
}

void VirtualShadowMap::recordPass(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const VirtualShadowMap& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    switch (r.kind) {
    case kInit:
        vkCmdFillBuffer(cmd, static_cast<VkBuffer>(self.m_pageTable.buffer.handle), 0, VK_WHOLE_SIZE, 0u);
        vkCmdFillBuffer(cmd, static_cast<VkBuffer>(self.m_physMeta.buffer.handle), 0, VK_WHOLE_SIZE, 0xFFFFFFFFu);
        return;
    case kReset:
        vkCmdUpdateBuffer(cmd, static_cast<VkBuffer>(self.m_work.buffer.handle), self.m_layout.counters, sizeof(kCounterInit),
                          kCounterInit);
        vkCmdFillBuffer(cmd, static_cast<VkBuffer>(self.m_work.buffer.handle), self.m_layout.request, self.m_layout.resetBytes, 0u);
        return;
    case kBoundsClear:
        vkCmdFillBuffer(cmd, static_cast<VkBuffer>(self.m_bounds.buffer.handle), 0, VK_WHOLE_SIZE, 0u);
        return;
    case kDispatch:
    case kDispatchIndirect:
        break;
    }
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipelines[r.kernel]));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(VsmPush),
                       &r.push);
    if (r.kind == kDispatchIndirect) {
        vkCmdDispatchIndirect(cmd, static_cast<VkBuffer>(self.m_work.buffer.handle), self.m_layout.counters);
    } else {
        vkCmdDispatch(cmd, r.groups[0], r.groups[1], r.groups[2]);
    }
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::vsm
